// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('RedHatDisplay');

const { fontFamily } = loadFont();



export type BlizzardStoryProps = Record<string, any>;

const BlizzardStory: React.FC<BlizzardStoryProps> = ({
  backgroundColor = "#020610",
  transparentBackground = false,
  durationInSeconds = 15,
  textColor = "#e2e8f0",
  accentColor = "#38bdf8",
  snowParticleCount = 150,
  storyLines = [
    "Suddenly the wind slammed my door shut,",
    "and as I went to open it, nothing moved.",
    "My car had locked me out—",
    "with the engine running—",
    "and my phone sat on the driver’s seat.",
    "So there I was: 1 a.m., middle of a blizzard,",
    "light sweater, no phone,",
    "stranded alone on the highway."
  ],
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Pre-calculate entry frames for each word to create a staggered typewriter effect
  const wordDelayFrames = 5;
  const linePauseFrames = 25;

  const timings = useMemo(() => {
    let currentFrame = 20; // Initial start delay
    const linesWithWords = storyLines.map((line) => {
      const words = line.split(" ");
      const startFrame = currentFrame;
      currentFrame += words.length * wordDelayFrames + linePauseFrames;
      return {
        words,
        startFrame,
      };
    });
    return linesWithWords;
  }, [storyLines]);

  // Generate random stable properties for snow particles
  const snowParticles = useMemo(() => {
    return Array.from({ length: snowParticleCount }).map((_, i) => ({
      id: i,
      x: random(`x-${i}`) * 100,
      size: random(`size-${i}`) * 4 + 1.5,
      speed: random(`speed-${i}`) * 2.5 + 1.0,
      sway: random(`sway-${i}`) * 2,
      swaySpeed: random(`swaySpeed-${i}`) * 0.03 + 0.01,
      opacity: random(`opacity-${i}`) * 0.5 + 0.1,
    }));
  }, [snowParticleCount]);

  // Responsive typography sizing
  const fontSize = width * 0.032;
  const paddingX = width * 0.12;
  const lineHeight = 1.6;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily }}>
      
      {/* Ambient center glow */}
      <div style={{
        position: "absolute",
        top: "50%", left: "50%",
        width: "90%", height: "90%",
        transform: "translate(-50%, -50%)",
        background: `radial-gradient(ellipse at center, ${accentColor}15 0%, transparent 60%)`,
        pointerEvents: "none",
        transition: "none",
      }} />

      {/* Snow Particles */}
      {snowParticles.map((p) => {
        const yPos = ((frame * p.speed) % 120) - 10;
        const xSway = Math.sin(frame * p.swaySpeed) * p.sway;
        return (
          <div
            key={p.id}
            style={{
              position: "absolute",
              left: `${p.x + xSway}%`,
              top: `${yPos}%`,
              width: p.size,
              height: p.size,
              backgroundColor: "#ffffff",
              borderRadius: "50%",
              opacity: p.opacity,
              filter: `blur(${p.size / 3}px)`,
              transition: "none",
              pointerEvents: "none",
            }}
          />
        );
      })}

      {/* Narrative Text Container */}
      <div style={{
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        textAlign: "center",
        width: "100%",
        height: "100%",
        paddingLeft: paddingX,
        paddingRight: paddingX,
        fontWeight: 600, // Semi-bold
        transition: "none",
      }}>
        {timings.map((lineData, lIdx) => (
          <div
            key={lIdx}
            style={{
              fontSize: `${fontSize}px`,
              lineHeight: lineHeight,
              color: textColor,
              marginBottom: lIdx === timings.length - 1 ? 0 : fontSize * 0.4,
              textAlign: "center",
              transition: "none",
            }}
          >
            {lineData.words.map((word, wIdx) => {
              const wordEntryFrame = lineData.startFrame + wIdx * wordDelayFrames;
              const opacity = interpolate(
                frame - wordEntryFrame,
                [0, 15],
                [0, 1],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );
              const yOffset = interpolate(
                frame - wordEntryFrame,
                [0, 15],
                [15, 0],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );

              return (
                <span
                  key={wIdx}
                  style={{
                    display: "inline-block",
                    marginRight: "0.25em",
                    opacity: opacity,
                    transform: `translateY(${yOffset}px)`,
                    transition: "none",
                    textShadow: `0px 4px 12px rgba(0,0,0,0.6)`
                  }}
                >
                  {word}
                </span>
              );
            })}
          </div>
        ))}
      </div>

      {/* Vignette Overlay for Depth and Suspense */}
      <div style={{
        position: "absolute",
        top: 0, left: 0,
        width: "100%", height: "100%",
        background: "radial-gradient(circle, transparent 40%, rgba(0,0,0,0.7) 120%)",
        pointerEvents: "none",
        transition: "none",
      }} />

    </AbsoluteFill>
  );
};

export default BlizzardStory;